import{_ as r,C as a,o as i,c as s,j as o,a as c,E as u,ak as d}from"./chunks/framework.CK0KoRlj.js";const _=JSON.parse('{"title":"Running OmniRoute on Kubernetes with omniroute-operator","description":"A Kubebuilder operator that turns one OmniRoute custom resource into a Deployment, Service, PVC, and Ingress.","frontmatter":{"title":"Running OmniRoute on Kubernetes with omniroute-operator","description":"A Kubebuilder operator that turns one OmniRoute custom resource into a Deployment, Service, PVC, and Ingress.","author":"vinaykumar","date":"2026-10-01T00:00:00.000Z","tags":["omniroute","kubernetes","operator"],"outline":"deep","editLink":false},"headers":[],"relativePath":"blog/running-omniroute-on-kubernetes.md","filePath":"blog/running-omniroute-on-kubernetes.md"}'),l={name:"blog/running-omniroute-on-kubernetes.md"};function p(t,e,m,h,g,b){const n=a("AuthorCard");return i(),s("div",null,[e[0]||(e[0]=o("h1",{id:"running-omniroute-on-kubernetes-with-omniroute-operator",tabindex:"-1"},[c("Running OmniRoute on Kubernetes with omniroute-operator "),o("a",{class:"header-anchor",href:"#running-omniroute-on-kubernetes-with-omniroute-operator","aria-label":'Permalink to "Running OmniRoute on Kubernetes with omniroute-operator"'},"​")],-1)),u(n,{author:t.$frontmatter.author},null,8,["author"]),e[1]||(e[1]=d('<p><a href="https://github.com/diegosouzapw/OmniRoute" target="_blank" rel="noreferrer">OmniRoute</a> is a unified AI proxy/router. <code>omniroute-operator</code> deploys and manages it on self-hosted Kubernetes, so an instance is one <code>kubectl apply</code> away.</p><h2 id="one-custom-resource-four-reconciled-objects" tabindex="-1">One custom resource, four reconciled objects <a class="header-anchor" href="#one-custom-resource-four-reconciled-objects" aria-label="Permalink to &quot;One custom resource, four reconciled objects&quot;">​</a></h2><p>The operator watches <code>OmniRoute</code> resources in the <code>gateway.omniroute.ai/v1alpha1</code> group and reconciles the Deployment, Service, PersistentVolumeClaim, and Ingress that make up an instance. Change the custom resource and the operator brings the cluster back in line.</p><p>Credentials come from an existing Secret containing <code>JWT_SECRET</code>, <code>API_KEY_SECRET</code>, and <code>INITIAL_PASSWORD</code>. Configuration can be injected from ConfigMaps, and <code>NODE_OPTIONS</code> is derived from the memory limit so the process does not get OOM-killed by a heap cap that ignores the container limit.</p><h2 id="things-worth-knowing-up-front" tabindex="-1">Things worth knowing up front <a class="header-anchor" href="#things-worth-knowing-up-front" aria-label="Permalink to &quot;Things worth knowing up front&quot;">​</a></h2><p><code>spec.replicas</code> is effectively capped at <code>1</code>, because OmniRoute stores state in SQLite with a single writer. An Ingress is opt-in: <code>spec.ingress.enabled</code> defaults to <code>false</code>, so enable it explicitly and set the class, host, and TLS if the instance must be reachable from outside the cluster. Disabling persistence makes the instance ephemeral.</p><p>Local development is supported with <code>k3d</code>, including running the controller outside the cluster against a local API server.</p><p>Read the <a href="/docs/omniroute-operator/">operator documentation</a> and the <a href="/docs/omniroute-operator/omniroute-cr">OmniRoute custom resource reference</a>. The project is Apache-2.0 licensed and ships a Helm chart for installation.</p>',8))])}const k=r(l,[["render",p]]);export{_ as __pageData,k as default};
